<?php
namespace App\Services;
use App\Models\DailyOrder; use App\Models\Order; use App\Models\RecurringPlan; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class RecurringOrderService {
 public function createPlan(array $data,int $userId):RecurringPlan{return DB::transaction(function()use($data,$userId){$plan=RecurringPlan::create(array_merge($this->planPayload($data),['plan_number'=>$this->nextPlanNumber(),'status'=>'draft','created_by'=>$userId]));$this->syncItems($plan,$data['items']);return $plan->fresh(['customer.user','items.product']);});}
 public function updatePlan(RecurringPlan $plan,array $data):RecurringPlan{if(!in_array($plan->status,['draft','paused'],true))throw ValidationException::withMessages(['plan'=>'Only draft or paused plans can be edited.']);return DB::transaction(function()use($plan,$data){$plan->update($this->planPayload($data));$plan->items()->delete();$this->syncItems($plan,$data['items']);return $plan->fresh(['customer.user','items.product']);});}
 public function approve(RecurringPlan $plan,int $userId):RecurringPlan{return DB::transaction(function()use($plan,$userId){if($plan->status!=='draft')throw ValidationException::withMessages(['plan'=>'Only draft plans can be approved.']);$next=$this->firstScheduleDate($plan->start_date,$plan->frequency,$plan->weekdays,$plan->day_of_month);$plan->update(['status'=>'active','approved_by'=>$userId,'approved_at'=>now(),'next_order_date'=>$next]);return $plan->fresh();});}
 public function pause(RecurringPlan $plan):RecurringPlan{if($plan->status!=='active')throw ValidationException::withMessages(['plan'=>'Only active plans can be paused.']);$plan->update(['status'=>'paused']);return $plan->fresh();}
 public function resume(RecurringPlan $plan):RecurringPlan{if($plan->status!=='paused')throw ValidationException::withMessages(['plan'=>'Only paused plans can be resumed.']);$next=$this->firstScheduleDate(max(today(),$plan->start_date),$plan->frequency,$plan->weekdays,$plan->day_of_month);$plan->update(['status'=>'active','next_order_date'=>$next]);return $plan->fresh();}
 public function cancel(RecurringPlan $plan):RecurringPlan{if(in_array($plan->status,['completed','cancelled'],true))throw ValidationException::withMessages(['plan'=>'Plan is already closed.']);$plan->update(['status'=>'cancelled']);$plan->dailyOrders()->whereIn('status',['pending','skipped'])->update(['status'=>'cancelled']);return $plan->fresh();}
 public function generateDue(?int $userId=null,?\DateTimeInterface $until=null):int{$until=$until?\Illuminate\Support\Carbon::parse($until):today();$count=0;RecurringPlan::where('status','active')->where('auto_generate',true)->whereNotNull('next_order_date')->whereDate('next_order_date','<=',$until)->orderBy('id')->chunkById(100,function($plans)use(&$count,$userId,$until){foreach($plans as $plan){while($plan->next_order_date && $plan->next_order_date->lte($until) && (!$plan->end_date || $plan->next_order_date->lte($plan->end_date))){$daily = $this->generateForDate($plan, $plan->next_order_date, $userId); if ($daily->wasRecentlyCreated) { $count++; }$plan->next_order_date=$this->nextDate($plan->next_order_date,$plan->frequency,$plan->weekdays,$plan->day_of_month);if($plan->end_date && $plan->next_order_date->gt($plan->end_date)){$plan->status='completed';$plan->next_order_date=null;break;} }$plan->save();}});return $count;}
 public function generateForDate(RecurringPlan $plan,$date,?int $userId=null):DailyOrder{return DB::transaction(function()use($plan,$date,$userId){$existing=DailyOrder::where('recurring_plan_id',$plan->id)->whereDate('scheduled_date',$date)->lockForUpdate()->first();if($existing)return $existing;$daily=DailyOrder::create(['daily_order_number'=>$this->nextDailyNumber(),'recurring_plan_id'=>$plan->id,'customer_id'=>$plan->customer_id,'scheduled_date'=>$date,'status'=>'pending','delivery_address'=>$plan->delivery_address,'delivery_city'=>$plan->delivery_city,'delivery_state'=>$plan->delivery_state,'delivery_pincode'=>$plan->delivery_pincode,'notes'=>$plan->notes]);$subtotal=0;$discount=0;$tax=0;foreach($plan->items as $i){$base=round((float)$i->quantity*(float)$i->unit_price,2);$disc=min($base,max(0,(float)$i->discount_amount));$taxable=max(0,$base-$disc);$itax=round($taxable*(float)$i->tax_rate/100,2);$line=round($taxable+$itax,2);$daily->items()->create(['product_id'=>$i->product_id,'design_id'=>$i->design_id,'description'=>$i->description,'quantity'=>$i->quantity,'unit'=>$i->unit,'unit_price'=>$i->unit_price,'discount_amount'=>$disc,'tax_rate'=>$i->tax_rate,'tax_amount'=>$itax,'line_total'=>$line,'sort_order'=>$i->sort_order]);$subtotal+=$base;$discount+=$disc;$tax+=$itax;}$daily->update(['grand_total'=>max(0,round($subtotal-$discount+$tax,2))]);return $daily->fresh(['items.product','customer']);});}
 public function convert(DailyOrder $daily,int $userId):Order{return DB::transaction(function()use($daily,$userId){$daily=DailyOrder::query()->lockForUpdate()->with('items')->findOrFail($daily->id);if($daily->status==='generated'&&$daily->order_id)return $daily->order;if(!in_array($daily->status,['pending'],true))throw ValidationException::withMessages(['daily_order'=>'Only pending daily orders can be generated.']);$order=Order::create(['order_number'=>app(OrderService::class)->generateOrderNumber(),'customer_id'=>$daily->customer_id,'order_date'=>$daily->scheduled_date,'required_date'=>$daily->scheduled_date,'status'=>'confirmed','delivery_address'=>$daily->delivery_address,'delivery_city'=>$daily->delivery_city,'delivery_state'=>$daily->delivery_state,'delivery_pincode'=>$daily->delivery_pincode,'created_by'=>$userId,'confirmed_by'=>$userId,'confirmed_at'=>now(),'internal_notes'=>'Generated from '.$daily->daily_order_number]);$subtotal=$discount=$tax=0;foreach($daily->items as $i){$order->items()->create(['product_id'=>$i->product_id,'design_id'=>$i->design_id,'description'=>$i->description,'quantity'=>$i->quantity,'unit'=>$i->unit,'unit_price'=>$i->unit_price,'discount_amount'=>$i->discount_amount,'tax_rate'=>$i->tax_rate,'tax_amount'=>$i->tax_amount,'line_total'=>$i->line_total,'sort_order'=>$i->sort_order]);$subtotal+=(float)$i->quantity*(float)$i->unit_price;$discount+=(float)$i->discount_amount;$tax+=(float)$i->tax_amount;}$order->update(['subtotal'=>$subtotal,'discount_amount'=>$discount,'tax_amount'=>$tax,'grand_total'=>max(0,round($subtotal-$discount+$tax,2))]);$daily->update(['status'=>'generated','order_id'=>$order->id,'generated_at'=>now(),'generated_by'=>$userId]);return $order->fresh(['customer','items.product']);});}
 private function planPayload(array $d):array{return ['customer_id'=>$d['customer_id'],'name'=>$d['name'],'frequency'=>$d['frequency'],'weekdays'=>$d['weekdays']??null,'day_of_month'=>$d['day_of_month']??null,'start_date'=>$d['start_date'],'end_date'=>$d['end_date']??null,'auto_generate'=>$d['auto_generate']??true,'delivery_address'=>$d['delivery_address']??null,'delivery_city'=>$d['delivery_city']??null,'delivery_state'=>$d['delivery_state']??null,'delivery_pincode'=>$d['delivery_pincode']??null,'notes'=>$d['notes']??null];}
 private function syncItems(RecurringPlan $plan,array $items):void{foreach(array_values($items) as $n=>$i){$plan->items()->create(['product_id'=>$i['product_id']??null,'design_id'=>$i['design_id']??null,'description'=>$i['description'],'quantity'=>$i['quantity'],'unit'=>$i['unit']??'bottle','unit_price'=>$i['unit_price'],'discount_amount'=>$i['discount_amount']??0,'tax_rate'=>$i['tax_rate']??0,'sort_order'=>$n,'metadata'=>$i['metadata']??null]);}}
 private function nextPlanNumber():string{return $this->sequence('recurring_plan_sequences','PLAN');} private function nextDailyNumber():string{return $this->sequence('daily_order_sequences','DORD');}
 private function sequence(string $table,string $prefix):string{$year=(int)now()->format('Y');$row=DB::table($table)->where('year',$year)->lockForUpdate()->first();if(!$row){DB::table($table)->insert(['year'=>$year,'next_number'=>2,'created_at'=>now(),'updated_at'=>now()]);$n=1;}else{$n=(int)$row->next_number;DB::table($table)->where('year',$year)->update(['next_number'=>$n+1,'updated_at'=>now()]);}return $prefix.'-'.$year.'-'.str_pad((string)$n,6,'0',STR_PAD_LEFT);}
 public function firstScheduleDate($date,string $frequency,?array $weekdays=null,?int $dom=null){$d=\Illuminate\Support\Carbon::parse($date);for($i=0;$i<370;$i++){if($this->matches($d,$frequency,$weekdays,$dom))return $d->copy();$d->addDay();}throw ValidationException::withMessages(['start_date'=>'No valid schedule date could be calculated.']);}
 private function nextDate($date,string $frequency,?array $weekdays=null,?int $dom=null){return $this->firstScheduleDate(\Illuminate\Support\Carbon::parse($date)->addDay(),$frequency,$weekdays,$dom);}
 private function matches($d,string $frequency,?array $weekdays,?int $dom):bool{return match($frequency){'daily'=>true,'weekly'=>in_array($d->dayOfWeekIso,array_map('intval',$weekdays??[]),true),'monthly'=>$d->day==($dom?:1),default=>false};}
}
